<script>
// ============================================================
// CHIP-8 Emulator - Complete Implementation
// ============================================================

// --- FONT SET (0x050 to 0x09F) ---
const FONT_SET = [
  0xF0,0x90,0x90,0x90,0xF0, // 0
  0x20,0x60,0x20,0x20,0x70, // 1
  0xF0,0x10,0xF0,0x80,0xF0, // 2
  0xF0,0x10,0xF0,0x10,0xF0, // 3
  0x90,0x90,0xF0,0x10,0x10, // 4
  0xF0,0x80,0xF0,0x10,0xF0, // 5
  0xF0,0x80,0xF0,0x90,0xF0, // 6
  0xF0,0x10,0x20,0x40,0x40, // 7
  0xF0,0x90,0xF0,0x90,0xF0, // 8
  0xF0,0x90,0xF0,0x10,0xF0, // 9
  0xF0,0x90,0xF0,0x90,0x90, // A
  0xE0,0x90,0xE0,0x90,0xE0, // B
  0xF0,0x80,0x80,0x80,0xF0, // C
  0xE0,0x90,0x90,0x90,0xE0, // D
  0xF0,0x80,0xF0,0x80,0xF0, // E
  0xF0,0x80,0xF0,0x80,0x80  // F
];

// --- DEMO ROM: "Bouncing Ball" ---
// A sprite (smiley) that bounces around the screen
// Assembled CHIP-8 bytecode:
// The program draws a smiley face sprite and allows moving it with keys 2(up),8(down),4(left),6(right)
// CHIP-8 key mapping: 2=up(W), 4=left(Q), 6=right(E), 8=down(S)
const DEMO_ROM = new Uint8Array([
  // Load sprite data address into I, draw smiley at (x=28, y=12)
  // Sprite: smiley face 8x8
  // V0 = x pos = 28, V1 = y pos = 12, V2 = speed delta
  0x60, 0x1C,  // 6XNN: V0 = 28 (x)
  0x61, 0x0C,  // 6XNN: V1 = 12 (y)
  0x62, 0x01,  // 6XNN: V2 = 1 (step size)
  0xA2, 0x20,  // ANNN: I = 0x220 (sprite data address, relative to 0x200 = offset 0x20)
  // Main loop: clear, draw, check keys, move
  // Label: LOOP at offset 0x08 (addr 0x208)
  0x00, 0xE0,  // 00E0: CLS - clear screen
  0xA2, 0x20,  // ANNN: I = sprite address (0x220)
  0xD0, 0x18,  // DXYN: draw 8 rows sprite at (V0, V1)
  // Check key 6 (right) = E key
  0x63, 0x06,  // V3 = 6
  0xE3, 0xA1,  // EXA1: skip if key V3 NOT pressed
  0x80, 0x24,  // 8XY4: V0 += V2 (move right)
  // Check key 4 (left) = Q key
  0x63, 0x04,  // V3 = 4
  0xE3, 0xA1,  // skip if key 4 NOT pressed
  0x80, 0x25,  // 8XY5: V0 -= V2 (move left)
  // Check key 2 (up) = W key  
  0x63, 0x02,  // V3 = 2
  0xE3, 0xA1,  // skip if key 2 NOT pressed
  0x81, 0x25,  // V1 -= V2 (move up)
  // Check key 8 (down) = S key
  0x63, 0x08,  // V3 = 8
  0xE3, 0xA1,  // skip if key 8 NOT pressed
  0x81, 0x24,  // V1 += V2 (move down)
  // Clamp X: if V0 > 56, set V0 = 56
  0x64, 0x38,  // V4 = 56
  0x84, 0x05,  // 8XY5: V4 = V4 - V0, VF=borrow
  0x3F, 0x00,  // skip if VF == 0 (no borrow means V0 <= 56)
  0x60, 0x38,  // V0 = 56
  // Clamp X: if V0 > 127 (wrapped negative), set V0 = 0
  0x64, 0x80,  // V4 = 128
  0x50, 0x40,  // skip if V0 == V4? No... use different approach
  // Actually check if V0 >= 128 (sign bit set = went negative)
  0x64, 0x7F,  // V4 = 127
  0x84, 0x05,  // V4 = V4 - V0
  0x4F, 0x00,  // skip if VF != 0 (V4 < V0, meaning V0 > 127)
  0x12, 0x2C,  // jump to CLAMP_Y (skip set V0=0)
  0x60, 0x00,  // V0 = 0
  // CLAMP_Y: clamp Y 0..23
  0x64, 0x17,  // V4 = 23
  0x84, 0x15,  // V4 = V4 - V1
  0x3F, 0x00,  // skip if VF==0 (V1 <= 23)
  0x61, 0x17,  // V1 = 23
  0x64, 0x7F,  // V4 = 127
  0x84, 0x15,  // V4 = V4 - V1
  0x4F, 0x00,  // skip if VF != 0
  0x12, 0x44,  // jump past reset
  0x61, 0x00,  // V1 = 0
  // Wait for timer (delay ~1 frame)
  0x65, 0x04,  // V5 = 4
  0xF5, 0x15,  // set delay timer = V5
  0xF5, 0x07,  // V5 = delay timer
  0x35, 0x00,  // skip if V5 == 0
  0x12, 0x48,  // loop back to timer check
  // Jump back to LOOP
  0x12, 0x08,  // JP 0x208

  // Sprite data at offset 0x20 (addr 0x220): 8x8 smiley face
  0x3C, // 00111100
  0x42, // 01000010
  0xA5, // 10100101
  0x81, // 10000001
  0xA5, // 10100101
  0x99, // 10011001
  0x42, // 01000010
  0x3C, // 00111100
]);

// --- CHIP-8 CPU ---
class Chip8 {
  constructor() {
    this.memory = new Uint8Array(4096);
    this.V = new Uint8Array(16);       // V0-VF
    this.I = 0;                         // Index register
    this.PC = 0x200;                    // Program counter
    this.stack = [];                    // Call stack
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(64 * 32); // 1 bit per pixel
    this.keys = new Uint8Array(16);     // Key states
    this.waitingForKey = -1;            // -1 = not waiting, else register index
    this.halted = false;
    this.lastOpcode = 0;
    this.loadFont();
  }

  loadFont() {
    for (let i = 0; i < FONT_SET.length; i++) {
      this.memory[0x050 + i] = FONT_SET[i];
    }
  }

  loadROM(data) {
    this.reset();
    for (let i = 0; i < data.length && (0x200 + i) < 4096; i++) {
      this.memory[0x200 + i] = data[i];
    }
  }

  reset() {
    this.memory = new Uint8Array(4096);
    this.V = new Uint8Array(16);
    this.I = 0;
    this.PC = 0x200;
    this.stack = [];
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(64 * 32);
    this.keys = new Uint8Array(16);
    this.waitingForKey = -1;
    this.halted = false;
    this.lastOpcode = 0;
    this.loadFont();
  }

  tickTimers() {
    if (this.delayTimer > 0) this.delayTimer--;
    if (this.soundTimer > 0) this.soundTimer--;
  }

  // Execute one instruction, return decoded string
  step() {
    if (this.halted) return 'HALTED';
    if (this.waitingForKey >= 0) return 'WAIT KEY';

    if (this.PC >= 4096) { this.halted = true; return 'PC OUT OF RANGE'; }

    const opcode = (this.memory[this.PC] << 8) | this.memory[this.PC + 1];
    this.lastOpcode = opcode;
    this.PC += 2;

    const nnn = opcode & 0x0FFF;
    const nn  = opcode & 0x00FF;
    const n   = opcode & 0x000F;
    const x   = (opcode >> 8) & 0x0F;
    const y   = (opcode >> 4) & 0x0F;

    let decoded = `${opcode.toString(16).toUpperCase().padStart(4,'0')} `;

    switch (opcode & 0xF000) {
      case 0x0000:
        if (opcode === 0x00E0) {
          this.display.fill(0);
          decoded += 'CLS';
        } else if (opcode === 0x00EE) {
          if (this.stack.length === 0) { this.halted = true; return decoded + 'RET (empty stack)'; }
          this.PC = this.stack.pop();
          decoded += `RET → 0x${this.PC.toString(16).toUpperCase()}`;
        } else {
          decoded += `SYS 0x${nnn.toString(16).toUpperCase()} (ignored)`;
        }
        break;

      case 0x1000:
        this.PC = nnn;
        decoded += `JP 0x${nnn.toString(16).toUpperCase()}`;
        break;

      case 0x2000:
        this.stack.push(this.PC);
        this.PC = nnn;
        decoded += `CALL 0x${nnn.toString(16).toUpperCase()}`;
        break;

      case 0x3000:
        if (this.V[x] === nn) this.PC += 2;
        decoded += `SE V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`;
        break;

      case 0x4000:
        if (this.V[x] !== nn) this.PC += 2;
        decoded += `SNE V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`;
        break;

      case 0x5000:
        if (this.V[x] === this.V[y]) this.PC += 2;
        decoded += `SE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
        break;

      case 0x6000:
        this.V[x] = nn;
        decoded += `LD V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`;
        break;

      case 0x7000:
        this.V[x] = (this.V[x] + nn) & 0xFF;
        decoded += `ADD V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`;
        break;

      case 0x8000:
        switch (n) {
          case 0x0:
            this.V[x] = this.V[y];
            decoded += `LD V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            break;
          case 0x1:
            this.V[x] |= this.V[y];
            this.V[0xF] = 0; // CHIP-8 original behavior
            decoded += `OR V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            break;
          case 0x2:
            this.V[x] &= this.V[y];
            this.V[0xF] = 0;
            decoded += `AND V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            break;
          case 0x3:
            this.V[x] ^= this.V[y];
            this.V[0xF] = 0;
            decoded += `XOR V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
            break;
          case 0x4: {
            const sum = this.V[x] + this.V[y];
            this.V[x] = sum & 0xFF;
            this.V[0xF] = sum > 255 ? 1 : 0;
            decoded += `ADD V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()} [carry=${this.V[0xF]}]`;
            break;
          }
          case 0x5: {
            const vx5 = this.V[x], vy5 = this.V[y];
            this.V[x] = (vx5 - vy5) & 0xFF;
            this.V[0xF] = vx5 >= vy5 ? 1 : 0;
            decoded += `SUB V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()} [borrow=${this.V[0xF]}]`;
            break;
          }
          case 0x6: {
            const lsb = this.V[y] & 0x1;
            this.V[x] = (this.V[y] >> 1) & 0xFF;
            this.V[0xF] = lsb;
            decoded += `SHR V${x.toString(16).toUpperCase()} [out=${lsb}]`;
            break;
          }
          case 0x7: {
            const vx7 = this.V[x], vy7 = this.V[y];
            this.V[x] = (vy7 - vx7) & 0xFF;
            this.V[0xF] = vy7 >= vx7 ? 1 : 0;
            decoded += `SUBN V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()} [borrow=${this.V[0xF]}]`;
            break;
          }
          case 0xE: {
            const msb = (this.V[y] >> 7) & 0x1;
            this.V[x] = (this.V[y] << 1) & 0xFF;
            this.V[0xF] = msb;
            decoded += `SHL V${x.toString(16).toUpperCase()} [out=${msb}]`;
            break;
          }
          default:
            decoded += `UNKNOWN 8XY${n.toString(16).toUpperCase()}`;
        }
        break;

      case 0x9000:
        if (this.V[x] !== this.V[y]) this.PC += 2;
        decoded += `SNE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
        break;

      case 0xA000:
        this.I = nnn;
        decoded += `LD I, 0x${nnn.toString(16).toUpperCase()}`;
        break;

      case 0xB000:
        this.PC = (nnn + this.V[0]) & 0xFFFF;
        decoded += `JP V0, 0x${nnn.toString(16).toUpperCase()}`;
        break;

      case 0xC000: {
        const rnd = Math.floor(Math.random() * 256);
        this.V[x] = rnd & nn;
        decoded += `RND V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`;
        break;
      }

      case 0xD000: {
        // Draw sprite at (Vx, Vy), N rows tall
        const px = this.V[x] & 63;
        const py = this.V[y] & 31;
        this.V[0xF] = 0;
        for (let row = 0; row < n; row++) {
          const sy = (py + row);
          if (sy >= 32) break;
          const spriteByte = this.memory[this.I + row];
          for (let col = 0; col < 8; col++) {
            const sx = (px + col);
            if (sx >= 64) break;
            if ((spriteByte >> (7 - col)) & 1) {
              const idx = sy * 64 + sx;
              if (this.display[idx]) this.V[0xF] = 1;
              this.display[idx] ^= 1;
            }
          }
        }
        decoded += `DRW V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}, ${n}`;
        break;
      }

      case 0xE000:
        if (nn === 0x9E) {
          if (this.keys[this.V[x] & 0xF]) this.PC += 2;
          decoded += `SKP V${x.toString(16).toUpperCase()}`;
        } else if (nn === 0xA1) {
          if (!this.keys[this.V[x] & 0xF]) this.PC += 2;
          decoded += `SKNP V${x.toString(16).toUpperCase()}`;
        } else {
          decoded += `UNKNOWN EX${nn.toString(16).toUpperCase()}`;
        }
        break;

      case 0xF000:
        switch (nn) {
          case 0x07:
            this.V[x] = this.delayTimer;
            decoded += `LD V${x.toString(16).toUpperCase()}, DT`;
            break;
          case 0x0A:
            // Wait for key press
            this.waitingForKey = x;
            decoded += `LD V${x.toString(16).toUpperCase()}, K (waiting...)`;
            break;
          case 0x15:
            this.delayTimer = this.V[x];
            decoded += `LD DT, V${x.toString(16).toUpperCase()}`;
            break;
          case 0x18:
            this.soundTimer = this.V[x];
            decoded += `LD ST, V${x.toString(16).toUpperCase()}`;
            break;
          case 0x1E:
            this.I = (this.I + this.V[x]) & 0xFFFF;
            decoded += `ADD I, V${x.toString(16).toUpperCase()}`;
            break;
          case 0x29:
            this.I = 0x050 + (this.V[x] & 0xF) * 5;
            decoded += `LD F, V${x.toString(16).toUpperCase()}`;
            break;
          case 0x33: {
            const bcd = this.V[x];
            this.memory[this.I]     = Math.floor(bcd / 100);
            this.memory[this.I + 1] = Math.floor((bcd % 100) / 10);
            this.memory[this.I + 2] = bcd % 10;
            decoded += `LD B, V${x.toString(16).toUpperCase()} (BCD=${Math.floor(bcd/100)},${Math.floor((bcd%100)/10)},${bcd%10})`;
            break;
          }
          case 0x55:
            for (let i = 0; i <= x; i++) this.memory[this.I + i] = this.V[i];
            // Classic CHIP-8: I += x + 1 (some implementations don't modify I)
            decoded += `LD [I], V0-V${x.toString(16).toUpperCase()}`;
            break;
          case 0x65:
            for (let i = 0; i <= x; i++) this.V[i] = this.memory[this.I + i];
            decoded += `LD V0-V${x.toString(16).toUpperCase()}, [I]`;
            break;
          default:
            decoded += `UNKNOWN FX${nn.toString(16).toUpperCase()}`;
        }
        break;

      default:
        decoded += `UNKNOWN ${opcode.toString(16).toUpperCase()}`;
    }

    return decoded;
  }

  // Called when a key is pressed (for FX0A wait)
  pressKey(k) {
    this.keys[k] = 1;
    if (this.waitingForKey >= 0) {
      this.V[this.waitingForKey] = k;
      this.waitingForKey = -1;
    }
  }

  releaseKey(k) {
    this.keys[k] = 0;
  }
}

// --- EMULATOR CONTROLLER ---
const chip8 = new Chip8();
let running = false;
let animFrameId = null;
let lastDecodedInstr = '---';
let timerAccum = 0;
let lastTimestamp = 0;
let instructionsPerFrame = 10;

// Canvas setup
const canvas = document.getElementById('screen');
const ctx = canvas.getContext('2d');
const SCALE = 10; // 64*10=640, 32*10=320

function renderDisplay() {
  ctx.fillStyle = '#0a1628';
  ctx.fillRect(0, 0, 640, 320);
  ctx.fillStyle = '#00ff88';
  for (let y = 0; y < 32; y++) {
    for (let x = 0; x < 64; x++) {
      if (chip8.display[y * 64 + x]) {
        ctx.fillRect(x * SCALE, y * SCALE, SCALE, SCALE);
      }
    }
  }
}

function updateDebugger() {
  document.getElementById('dbgPC').textContent = '0x' + chip8.PC.toString(16).toUpperCase().padStart(3,'0');
  document.getElementById('dbgI').textContent  = '0x' + chip8.I.toString(16).toUpperCase().padStart(3,'0');
  document.getElementById('dbgDT').textContent = chip8.delayTimer;
  document.getElementById('dbgST').textContent = chip8.soundTimer;
  document.getElementById('dbgInstr').textContent = lastDecodedInstr;

  const regsDiv = document.getElementById('registers');
  regsDiv.innerHTML = '';
  for (let i = 0; i < 16; i++) {
    const d = document.createElement('div');
    d.className = 'reg';
    const name = i < 10 ? `V${i}` : `V${String.fromCharCode(55+i)}`;
    d.innerHTML = `<div class="reg-name">${name}</div><div class="reg-val">0x${chip8.V[i].toString(16).toUpperCase().padStart(2,'0')}</div>`;
    regsDiv.appendChild(d);
  }

  const stackDiv = document.getElementById('dbgStack');
  if (chip8.stack.length === 0) {
    stackDiv.textContent = 'empty';
  } else {
    stackDiv.textContent = chip8.stack.map((v,i) => `[${i}] 0x${v.toString(16).toUpperCase().padStart(3,'0')}`).join('  ');
  }
}

function setStatus(msg, color) {
  const sb = document.getElementById('statusBar');
  sb.innerHTML = `Status: <span style="color:${color||'#00d4ff'}">${msg}</span>`;
}

// --- MAIN LOOP ---
function mainLoop(timestamp) {
  if (!running) return;

  const dt = timestamp - lastTimestamp;
  lastTimestamp = timestamp;

  // Execute instructions
  for (let i = 0; i < instructionsPerFrame; i++) {
    if (!chip8.halted && chip8.waitingForKey < 0) {
      lastDecodedInstr = chip8.step();
    }
  }

  // Tick timers at ~60Hz
  timerAccum += dt;
  if (timerAccum >= 16.667) {
    chip8.tickTimers();
    timerAccum -= 16.667;
  }

  renderDisplay();
  updateDebugger();

  if (chip8.halted) {
    setStatus('HALTED', '#ff4444');
    running = false;
    return;
  }

  animFrameId = requestAnimationFrame(mainLoop);
}

function startRun() {
  if (running) return;
  running = true;
  lastTimestamp = performance.now();
  timerAccum = 0;
  setStatus('Running', '#00ff88');
  document.getElementById('btnRun').classList.add('active');
  document.getElementById('btnPause').classList.remove('active');
  animFrameId = requestAnimationFrame(mainLoop);
}

function pause() {
  running = false;
  if (animFrameId) { cancelAnimationFrame(animFrameId); animFrameId = null; }
  setStatus('Paused', '#ffcc00');
  document.getElementById('btnRun').classList.remove('active');
  document.getElementById('btnPause').classList.add('active');
  updateDebugger();
}

function step() {
  if (running) pause();
  lastDecodedInstr = chip8.step();
  chip8.tickTimers();
  renderDisplay();
  updateDebugger();
  setStatus('Stepped', '#ffcc00');
}

function reset() {
  pause();
  const romBackup = currentROM;
  chip8.reset();
  if (romBackup) chip8.loadROM(romBackup);
  lastDecodedInstr = '---';
  renderDisplay();
  updateDebugger();
  setStatus('Reset', '#ffcc00');
}

// --- ROM MANAGEMENT ---
let currentROM = null;

function loadDemoROM() {
  pause();
  currentROM = DEMO_ROM;
  chip8.loadROM(DEMO_ROM);
  lastDecodedInstr = '---';
  renderDisplay();
  updateDebugger();
  setStatus('Demo ROM loaded', '#00d4ff');
}

// --- KEYPAD ---
// CHIP-8 key layout:
// 1 2 3 C
// 4 5 6 D
// 7 8 9 E
// A 0 B F
const CHIP8_KEYS = [
  {chip8: 0x1, kb: '1'}, {chip8: 0x2, kb: '2'}, {chip8: 0x3, kb: '3'}, {chip8: 0xC, kb: '4'},
  {chip8: 0x4, kb: 'Q'}, {chip8: 0x5, kb: 'W'}, {chip8: 0x6, kb: 'E'}, {chip8: 0xD, kb: 'R'},
  {chip8: 0x7, kb: 'A'}, {chip8: 0x8, kb: 'S'}, {chip8: 0x9, kb: 'D'}, {chip8: 0xE, kb: 'F'},
  {chip8: 0xA, kb: 'Z'}, {chip8: 0x0, kb: 'X'}, {chip8: 0xB, kb: 'C'}, {chip8: 0xF, kb: 'V'},
];

const KB_TO_CHIP8 = {};
CHIP8_KEYS.forEach(k => { KB_TO_CHIP8[k.kb] = k.chip8; });

function buildKeypad() {
  const kp = document.getElementById('keypad');
  kp.innerHTML = '';
  CHIP8_KEYS.forEach(k => {
    const div = document.createElement('div');
    div.className = 'key';
    div.id = `key-${k.chip8}`;
    div.innerHTML = `<div class="chip8-key">${k.chip8.toString(16).toUpperCase()}</div><div class="kb-key">${k.kb}</div>`;
    kp.appendChild(div);
  });
}

function setKeyVisual(chip8Key, pressed) {
  const el = document.getElementById(`key-${chip8Key}`);
  if (el) el.classList.toggle('pressed', pressed);
}

document.addEventListener('keydown', e => {
  const key = e.key.toUpperCase();
  if (key in KB_TO_CHIP8) {
    e.preventDefault();
    const ck = KB_TO_CHIP8[key];
    chip8.pressKey(ck);
    setKeyVisual(ck, true);
  }
});

document.addEventListener('keyup', e => {
  const key = e.key.toUpperCase();
  if (key in KB_TO_CHIP8) {
    e.preventDefault();
    const ck = KB_TO_CHIP8[key];
    chip8.releaseKey(ck);
    setKeyVisual(ck, false);
  }
});

// --- CONTROLS ---
document.getElementById('btnRun').addEventListener('click', startRun);
document.getElementById('btnPause').addEventListener('click', pause);
document.getElementById('btnStep').addEventListener('click', step);
document.getElementById('btnReset').addEventListener('click', reset);
document.getElementById('btnDemo').addEventListener('click', loadDemoROM);

const speedSlider = document.getElementById('speedSlider');
const speedVal = document.getElementById('speedVal');
speedSlider.addEventListener('input', () => {
  instructionsPerFrame = parseInt(speedSlider.value);
  speedVal.textContent = `${instructionsPerFrame} i/f`;
});

document.getElementById('romFile').addEventListener('change', e => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = ev => {
    pause();
    currentROM = new Uint8Array(ev.target.result);
    chip8.loadROM(currentROM);
    lastDecodedInstr = '---';
    renderDisplay();
    updateDebugger();
    setStatus(`ROM loaded: ${file.name}`, '#00d4ff');
  };
  reader.readAsArrayBuffer(file);
  e.target.value = '';
});

// --- INIT ---
buildKeypad();
loadDemoROM();
startRun();
</script>
</body>
</html>
```

